//! Known-answer tests against **real** `cryptsetup`/dm-crypt output —
//! Tier 1 evidence per `specs/fips_check.md`: bit-for-bit compatibility
//! with the actual tool this project replaces, not just standards
//! conformance (that's what `kat_ieee1619.rs` covers).
//!
//! Provenance: generated on a Hyper-V Ubuntu 22.04 VM (Linux 5.15.0,
//! `cryptsetup` 2.4.3 — a real kernel, not a WSL2 build, after WSL2's
//! dm-crypt write path was found to reproducibly wedge in an
//! uninterruptible kernel sleep on this machine's WSL2 kernel build).
//! Each vector: `cryptsetup open --type plain` on a loop-backed file
//! with a known key, a known plaintext `dd`'d through the resulting
//! `/dev/mapper/*` device, then the ciphertext read straight back out
//! of the backing file. `--skip <N>` sets the IV/tweak sector number
//! independently of `--offset`, letting nonzero-sector vectors use a
//! tiny backing file instead of actually allocating N sectors. Hex
//! extracted programmatically (never hand-transcribed) from the
//! generation script's own output file.
//!
//! Coverage the IEEE vectors don't provide: a huge sector index
//! (0x75bcd15) exercising every tweak byte, and `aes-cbc-essiv:sha256`
//! (both single- and multi-sector, the latter checking the per-sector
//! IV reset + intra-sector CBC chaining together) — IEEE 1619 Annex B
//! only covers XTS.

use nocap_crypt_core::{CipherSpec, SectorEngine};

// VEC_A_XTS256_S0: cipher=aes-xts-plain64 key_size_bits=512 skip_sectors=0 nsectors=1
const VEC_A_XTS256_S0_KEY: &str = "000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f202122232425262728292a2b2c2d2e2f303132333435363738393a3b3c3d3e3f";
const VEC_A_XTS256_S0_PTX: &str = "";
const VEC_A_XTS256_S0_CTX: &str = "";
const VEC_A_SKIP_SECTORS: u64 = 0;

// VEC_B_XTS256_BIGNSECTOR: cipher=aes-xts-plain64 key_size_bits=512 skip_sectors=123456789 nsectors=2
const VEC_B_XTS256_BIGNSECTOR_KEY: &str = "404142434445464748494a4b4c4d4e4f505152535455565758595a5b5c5d5e5f606162636465666768696a6b6c6d6e6f707172737475767778797a7b7c7d7e7f";
const VEC_B_XTS256_BIGNSECTOR_PTX: &str = "";
const VEC_B_XTS256_BIGNSECTOR_CTX: &str = "";
const VEC_B_SKIP_SECTORS: u64 = 123456789;

// VEC_C_XTS128_S0: cipher=aes-xts-plain64 key_size_bits=256 skip_sectors=0 nsectors=1
const VEC_C_XTS128_S0_KEY: &str = "808182838485868788898a8b8c8d8e8f909192939495969798999a9b9c9d9e9f";
const VEC_C_XTS128_S0_PTX: &str = "";
const VEC_C_XTS128_S0_CTX: &str = "";
const VEC_C_SKIP_SECTORS: u64 = 0;

// VEC_D_XTS128_S7: cipher=aes-xts-plain64 key_size_bits=256 skip_sectors=7 nsectors=1
const VEC_D_XTS128_S7_KEY: &str = "a0a1a2a3a4a5a6a7a8a9aaabacadaeafb0b1b2b3b4b5b6b7b8b9babbbcbdbebf";
const VEC_D_XTS128_S7_PTX: &str = "";
const VEC_D_XTS128_S7_CTX: &str = "";
const VEC_D_SKIP_SECTORS: u64 = 7;

// VEC_E_CBCESSIV_S0: cipher=aes-cbc-essiv:sha256 key_size_bits=256 skip_sectors=0 nsectors=1
const VEC_E_CBCESSIV_S0_KEY: &str = "c0c1c2c3c4c5c6c7c8c9cacbcccdcecfd0d1d2d3d4d5d6d7d8d9dadbdcdddedf";
const VEC_E_CBCESSIV_S0_PTX: &str = "";
const VEC_E_CBCESSIV_S0_CTX: &str = "";
const VEC_E_SKIP_SECTORS: u64 = 0;

// VEC_F_CBCESSIV_MULTI: cipher=aes-cbc-essiv:sha256 key_size_bits=256 skip_sectors=3 nsectors=3
const VEC_F_CBCESSIV_MULTI_KEY: &str = "e0e1e2e3e4e5e6e7e8e9eaebecedeeeff0f1f2f3f4f5f6f7f8f9fafbfcfdfeff";
const VEC_F_CBCESSIV_MULTI_PTX: &str = "";
const VEC_F_CBCESSIV_MULTI_CTX: &str = "";
const VEC_F_SKIP_SECTORS: u64 = 3;

fn run_xts_vector(key_hex: &str, aes_bits: u16, sector: u64, ptx_hex: &str, ctx_hex: &str) {
    let key = hex::decode(key_hex).unwrap();
    let ptx = hex::decode(ptx_hex).unwrap();
    let ctx = hex::decode(ctx_hex).unwrap();

    let spec = CipherSpec::parse("aes-xts-plain64").unwrap().with_aes_bits(aes_bits).unwrap();
    let engine = SectorEngine::new(spec, &key).unwrap();

    let mut encrypted = ptx.clone();
    engine.encrypt_range(sector, &mut encrypted);
    assert_eq!(encrypted, ctx, "encryption did not match real cryptsetup output");

    let mut decrypted = ctx.clone();
    engine.decrypt_range(sector, &mut decrypted);
    assert_eq!(decrypted, ptx, "decryption did not recover the plaintext cryptsetup was given");
}

fn run_cbc_essiv_vector(key_hex: &str, sector: u64, ptx_hex: &str, ctx_hex: &str) {
    let key = hex::decode(key_hex).unwrap();
    let ptx = hex::decode(ptx_hex).unwrap();
    let ctx = hex::decode(ctx_hex).unwrap();

    let spec = CipherSpec::parse("aes-cbc-essiv:sha256").unwrap();
    let engine = SectorEngine::new(spec, &key).unwrap();

    let mut encrypted = ptx.clone();
    engine.encrypt_range(sector, &mut encrypted);
    assert_eq!(encrypted, ctx, "encryption did not match real cryptsetup output");

    let mut decrypted = ctx.clone();
    engine.decrypt_range(sector, &mut decrypted);
    assert_eq!(decrypted, ptx, "decryption did not recover the plaintext cryptsetup was given");
}

#[test]
fn kat_cryptsetup_xts256_sector0() {
    run_xts_vector(VEC_A_XTS256_S0_KEY, 256, VEC_A_SKIP_SECTORS, VEC_A_XTS256_S0_PTX, VEC_A_XTS256_S0_CTX);
}

#[test]
fn kat_cryptsetup_xts256_huge_sector_index() {
    run_xts_vector(
        VEC_B_XTS256_BIGNSECTOR_KEY,
        256,
        VEC_B_SKIP_SECTORS,
        VEC_B_XTS256_BIGNSECTOR_PTX,
        VEC_B_XTS256_BIGNSECTOR_CTX,
    );
}

#[test]
fn kat_cryptsetup_xts128_sector0() {
    run_xts_vector(VEC_C_XTS128_S0_KEY, 128, VEC_C_SKIP_SECTORS, VEC_C_XTS128_S0_PTX, VEC_C_XTS128_S0_CTX);
}

#[test]
fn kat_cryptsetup_xts128_sector7() {
    run_xts_vector(VEC_D_XTS128_S7_KEY, 128, VEC_D_SKIP_SECTORS, VEC_D_XTS128_S7_PTX, VEC_D_XTS128_S7_CTX);
}

#[test]
fn kat_cryptsetup_cbc_essiv_sector0() {
    run_cbc_essiv_vector(VEC_E_CBCESSIV_S0_KEY, VEC_E_SKIP_SECTORS, VEC_E_CBCESSIV_S0_PTX, VEC_E_CBCESSIV_S0_CTX);
}

#[test]
fn kat_cryptsetup_cbc_essiv_multi_sector_nonzero_start() {
    run_cbc_essiv_vector(VEC_F_CBCESSIV_MULTI_KEY, VEC_F_SKIP_SECTORS, VEC_F_CBCESSIV_MULTI_PTX, VEC_F_CBCESSIV_MULTI_CTX);
}
